        var(g,r)=Start();Play(g);var equipment=EquipAndQirang(g);var paid=E<QirangGainPaidEvent>(g).Single();Need(V(g,0).Hand.Any(c=>c.Id==paid.CardId)&&paid.Kind==CardKind.Duel,"A real equipment Use obtains one actual ordered-deck Trick entity.");
        var other=V(g,0).Hand.First(c=>c.Kind==CardKind.Duel&&c.Id!=paid.CardId);NativeUse(g,other.Id,[1]);Reach(g,()=>P(g)is{PlayerSeat:0,Kind:DecisionKind.PlayCard}||P(g)?.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="qirang-extra-target")==true);Need(P(g)is{Kind:DecisionKind.PlayCard},"Another ordinary Trick of the same kind cannot borrow the acquired entity's extra target right.");
        NativeUse(g,paid.CardId,[1]);Reach(g,()=>OptionalQirang(g));Answer(g,c=>c.Parameters.GetValueOrDefault("program-action")=="activate");Reach(g,()=>P(g)?.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="qirang-extra-target")==true);var parent=g.ResolutionStack.OfType<ProgramSkillFrame>().Single(f=>f.ZhugeGuo?.Stage==ZhugeGuoStage.ExtraTargetChoice).ZhugeGuo!;
