    private static void FinishPeek(GameEngine g){while(P(g)is{Kind:DecisionKind.ProgramTopReorder})Answer(g,c=>c.Parameters.GetValueOrDefault("action")=="top");}
    private static void Play(GameEngine g)=>Reach(g,()=>P(g)is{PlayerSeat:0,Kind:DecisionKind.PlayCard});
